begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
insert into auth.users(id) values('ba8b2af4-a8b5-4b31-9d13-578f15bba750');
insert into public.materials(id,name,manufacturer_name) values('ba8b2af4-a8b5-4b31-9d13-578f15bba751','資料・登録テスト資材','元の会社');
insert into storage.objects(bucket_id,name) values
('manufacturer-drafts','33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/11111111-1111-4111-8111-111111111111.png'),
('manufacturer-drafts','33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/22222222-2222-4222-8222-222222222222.png');
select public.set_material_editor_grant('ba8b2af4-a8b5-4b31-9d13-578f15bba751','33333333-3333-4333-8333-333333333333','DETAILS-TEST','ba8b2af4-a8b5-4b31-9d13-578f15bba750');
create function pg_temp.content() returns jsonb language sql as $$ select '{"description":"製品説明","mainComponents":"","mechanism":"","links":[{"group":"public_trial","title":"試験報告","url":"https://example.com/report.pdf","trial":{"crops":"トマト","summary":"試験の概要","institution":"試験場","year":2025,"pageCount":5}}],"images":[],"usages":[],"timings":[],"certifications":["従来の自由文"],"registrations":[{"kind":"pesticide","companyName":"登録会社","effects":"登録効果"},{"kind":"soil_amendment","companyName":"表示会社","effects":""}],"relatedCompanies":["会社A","会社B"]}'::jsonb $$;
create function pg_temp.save(p jsonb, submit boolean) returns uuid language sql as $$
 select public.save_material_page_version('ba8b2af4-a8b5-4b31-9d13-578f15bba751',p,submit,(select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='draft'));
$$;
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","app_metadata":{"account_type":"seller","seller_id":"33333333-3333-4333-8333-333333333333"}}',true);
set local role authenticated;
select lives_ok($$select pg_temp.save(jsonb_set(jsonb_set(pg_temp.content(),'{links,0,group}','null'),'{links,0,trial}','null'),false)$$,'unclassified document can be drafted');
select is((select content_contract::integer from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='draft'),2,'new payload marks only its new version');
select throws_ok($$select pg_temp.save(pg_temp.content()-'registrations'-'relatedCompanies',false)$$,'40001',null,'old client cannot erase new contract history');
select throws_ok($$select pg_temp.save(pg_temp.content()-'registrations',false)$$,'23514',null,'partial new contract rejected');
select throws_ok($$select pg_temp.save(jsonb_set(jsonb_set(pg_temp.content(),'{links,0,group}','null'),'{links,0,trial}','null'),true)$$,'23514',null,'unclassified submission rejected');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links,0,trial,summary}','""'),true)$$,'23514',null,'trial summary required');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links,0,trial,institution}','""'),true)$$,'23514',null,'trial institution required');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links,0,trial,year}','1.5'),false)$$,'23514',null,'fractional year rejected');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links,0,trial,pageCount}','0'),false)$$,'23514',null,'zero pages rejected');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links,0,group}','null'),false)$$,'23514',null,'null category cannot carry trial data');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{links}',(pg_temp.content()->'links')||(pg_temp.content()->'links')),true)$$,'23514',null,'duplicate URL rejected');
select lives_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{registrations,0,companyName}','""'),false)$$,'registration company can be drafted empty');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{registrations,0,companyName}','""'),true)$$,'23514',null,'registration company required at submit');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{relatedCompanies}','["会社A"," 会社A "]'),true)$$,'23514',null,'duplicate related company rejected');
select throws_ok($$select pg_temp.save(jsonb_set(pg_temp.content(),'{registrations}','[null]'),false)$$,'23514',null,'malformed registration rejected');
select pg_temp.save(jsonb_set(pg_temp.content(),'{images}','[{"path":"33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/11111111-1111-4111-8111-111111111111.png","alt":"1"},{"path":"33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/22222222-2222-4222-8222-222222222222.png","alt":"2"}]'),false);
select set_config('test.old_version',(select id::text from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='draft'),true);
select pg_temp.save(jsonb_set(pg_temp.content(),'{images}','[{"path":"33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/22222222-2222-4222-8222-222222222222.png","alt":"2"},{"path":"33333333-3333-4333-8333-333333333333/ba8b2af4-a8b5-4b31-9d13-578f15bba751/11111111-1111-4111-8111-111111111111.png","alt":"1"}]'),false);
select is((select sort_order from public.material_page_images where version_id=current_setting('test.old_version')::uuid and alt='1'),0,'image reorder preserves previous version');
select is((select i.sort_order from public.material_page_images i join public.material_page_versions v on v.id=i.version_id where v.material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and v.status='draft' and i.alt='1'),1,'image reorder applies to new version');
select lives_ok($$select pg_temp.save(pg_temp.content(),true)$$,'complete trial and registrations submit');
select is((select count(*)::integer from public.material_page_registrations r join public.material_page_versions v on v.id=r.version_id where v.material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and v.status='pending'),2,'two registration kinds retained');
select is((select trial_summary from public.material_page_links l join public.material_page_versions v on v.id=l.version_id where v.material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and v.status='pending'),'試験の概要','trial summary round trips');
reset role;
select is((select seller_id::text from public.materials where id='ba8b2af4-a8b5-4b31-9d13-578f15bba751'),'33333333-3333-4333-8333-333333333333','related companies do not change representative');
select set_config('test.pending_version',(select id::text from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='pending'),true);
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::integer from public.material_page_registrations where version_id=current_setting('test.pending_version')::uuid),0,'unpublished registrations are hidden');
reset role;
update public.material_page_links set group_name=null,trial_crops=null,trial_summary=null,trial_institution=null,trial_year=null,trial_page_count=null where version_id=(select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='pending');
select throws_ok($$select public.review_material_page_version((select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='pending'),'ba8b2af4-a8b5-4b31-9d13-578f15bba750',true,'')$$,'23514',null,'approval revalidates classification');
select is((select published_page_version_id from public.materials where id='ba8b2af4-a8b5-4b31-9d13-578f15bba751'),null::uuid,'failed approval leaves public pointer unchanged');
update public.material_page_links set group_name='overview' where version_id=(select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='pending');
select lives_ok($$select public.review_material_page_version((select id from public.material_page_versions where material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751' and status='pending'),'ba8b2af4-a8b5-4b31-9d13-578f15bba750',true,'')$$,'complete version publishes');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::integer from public.material_page_registrations r join public.public_material_page_versions v on v.id=r.version_id where v.material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751'),2,'published registrations visible');
select is((select string_agg(r.company_name,'、' order by r.sort_order) from public.material_page_related_companies r join public.public_material_page_versions v on v.id=r.version_id where v.material_id='ba8b2af4-a8b5-4b31-9d13-578f15bba751'),'会社A、会社B','related companies retain order');
select throws_ok($$insert into public.material_page_registrations(version_id,kind,company_name) values('ba8b2af4-a8b5-4b31-9d13-578f15bba751','fertilizer','会社')$$,'42501',null,'anonymous cannot insert registrations');
reset role;
select * from finish();
rollback;
